--
-- Table structure for table `maintenance_record`
--

DROP TABLE IF EXISTS `maintenance_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `maintenance_record` (
  `maintenance_id` bigint NOT NULL AUTO_INCREMENT,
  `date` datetime NOT NULL,
  `work_done` text NOT NULL,
  `duration_minutes` int NOT NULL,
  `approval_status` varchar(30) NOT NULL DEFAULT 'PENDING',
  `approved_by` bigint DEFAULT NULL,
  PRIMARY KEY (`maintenance_id`),
  KEY `idx_maint_approved_by` (`approved_by`),
  CONSTRAINT `fk_maint_approved_by` FOREIGN KEY (`approved_by`) REFERENCES `staff` (`staff_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ck_maint_approval` CHECK ((`approval_status` in (_utf8mb4'PENDING',_utf8mb4'APPROVED',_utf8mb4'REJECTED'))),
  CONSTRAINT `ck_maint_duration` CHECK ((`duration_minutes` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

