DROP TABLE IF EXISTS `passenger_contact`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `passenger_contact` (
  `contact_id` bigint NOT NULL AUTO_INCREMENT,
  `passenger_id` bigint NOT NULL,
  `contact_type` varchar(30) NOT NULL,
  `value` varchar(200) NOT NULL,
  PRIMARY KEY (`contact_id`),
  KEY `idx_pcontact_passenger` (`passenger_id`),
  CONSTRAINT `fk_passenger_contact` FOREIGN KEY (`passenger_id`) REFERENCES `passenger` (`passenger_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_passenger_contact_type` CHECK ((`contact_type` in (_utf8mb4'PHONE',_utf8mb4'EMAIL',_utf8mb4'ADDRESS',_utf8mb4'OTHER')))
) ENGINE=InnoDB AUTO_INCREMENT=8002 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
