--
-- Table structure for table `staff_shift`
--

DROP TABLE IF EXISTS `staff_shift`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `staff_shift` (
  `shift_id` bigint NOT NULL AUTO_INCREMENT,
  `staff_id` bigint NOT NULL,
  `start_time` datetime NOT NULL,
  `end_time` datetime NOT NULL,
  `role_assigned` varchar(120) NOT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'SCHEDULED',
  PRIMARY KEY (`shift_id`),
  KEY `idx_shift_staff` (`staff_id`),
  CONSTRAINT `fk_shift_staff` FOREIGN KEY (`staff_id`) REFERENCES `staff` (`staff_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_shift_status` CHECK ((`status` in (_utf8mb4'SCHEDULED',_utf8mb4'ACTIVE',_utf8mb4'COMPLETED',_utf8mb4'SICK_LEAVE')))
) ENGINE=InnoDB AUTO_INCREMENT=321 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

